INSERT INTO `ingest_staging` VALUES (1455,'LOAD','LOADER-001','DEMO-1791544818455','2026-10-09 19:20:18','2026-10-09 19:20:18','{\"batchNos\": [\"SP20261009-001-05\"], \"loadTime\": \"2026-10-09 19:20:17\", \"driverName\": \"张师傅\"}','LOADER-001',3,'cold_chain_transport',NULL,'缺少车牌号(vehicleNo)：装车口必须先识别到车牌才能生成运单',NULL,NULL,NULL,'2026-10-09 19:20:18'),(1456,'LOAD','LOADER-001','DEMO-1791544818521','2026-10-09 19:20:19','2026-10-09 19:20:19','{\"loadTime\": \"2026-10-09 19:20:16\", \"vehicleNo\": \"京A·12345\", \"driverName\": \"张师傅\"}','LOADER-001',3,'cold_chain_transport',NULL,'缺少装车批次号(batchNos)：扫码枪须扫出本车装载的分割批次，系统才能倒查出发货计划',NULL,NULL,NULL,'2026-10-09 19:20:19'),(1457,'LOAD','LOADER-001','DEMO-1791544818578','2026-10-09 19:20:19','2026-10-09 19:20:19','{\"batchNos\": [\"SP20261009-001-05\"], \"loadTime\": \"2026-10-09 19:20:15\", \"vehicleNo\": \"京A·12345\"}','LOADER-001',1,'cold_chain_transport',NULL,'缺少司机姓名(driverName)：装车发运必须记录实际驾驶人，请司机在实名终端完成识别后重报',NULL,NULL,NULL,'2026-10-09 19:20:19'),(1458,'LOAD','LOADER-001','DEMO-1791544818627','2026-10-09 19:20:19','2026-10-09 19:20:19','{\"batchNos\": [\"SP-TEST-0003\"], \"loadTime\": \"2026-10-09 19:20:14\", \"vehicleNo\": \"京A·12345\", \"driverName\": \"张师傅\"}','LOADER-001',1,'cold_chain_transport',NULL,'扫到的货物（SP-TEST-0003）不属于任何待发货计划，无法确定该发去哪家店。装车口不猜目的地，请先建发货计划后重新扫码，或走人工建单',NULL,NULL,NULL,'2026-10-09 19:20:19'),(1459,'LOAD','LOADER-001','DEMO-1791544818714','2026-10-09 19:20:19','2026-10-09 19:20:19','{\"batchNos\": [\"SP20261009-001-02\"], \"loadTime\": \"2026-10-09 19:20:13\", \"vehicleNo\": \"京A·88888\", \"driverName\": \"李四\"}','LOADER-001',1,'cold_chain_transport',NULL,'装车口自动建单未通过：装车口识别的车牌号「京A·88888」与计划安排的「京A·99999」不一致，请人工核对是否装错车',NULL,NULL,NULL,'2026-10-09 19:20:19'),(1460,'LOAD','LOADER-001','DEMO-1791544818848','2026-10-09 19:20:19','2026-10-09 19:20:19','{\"batchNos\": [\"SP20261009-001-05\", \"SP20261009-001-04\", \"SP20261009-001-03\"], \"loadTime\": \"2026-10-09 19:20:12\", \"vehicleNo\": \"京A·12345\", \"driverName\": \"张师傅\", \"driverPhone\": \"13700000002\"}','LOADER-001',2,'cold_chain_transport',40,NULL,NULL,NULL,NULL,'2026-10-09 19:20:19'),(1461,'LOAD','LOADER-001','DEMO-1791544819048','2026-10-09 19:20:19','2026-10-09 19:20:19','{\"batchNos\": [\"SP20261009-001-05\"], \"loadTime\": \"2026-10-09 19:20:12\", \"vehicleNo\": \"京A·12345\", \"driverName\": \"张师傅\"}','LOADER-001',3,'cold_chain_transport',NULL,'分割批次 SP20261009-001-05 已由运单发运过，禁止重复装车（如确需重发请人工核对后处理）',NULL,NULL,NULL,'2026-10-09 19:20:19'),(1462,'LOAD','LOADER-001','DEMO-1791544819112','2026-10-09 19:20:19','2026-10-09 19:20:19','{\"batchNos\": [\"SP20261009-001-02\", \"SP20261009-001-01\"], \"loadTime\": \"2026-10-09 19:20:11\", \"vehicleNo\": \"京A·99999\", \"driverName\": \"李四\"}','LOADER-001',2,'cold_chain_transport',41,NULL,NULL,NULL,NULL,'2026-10-09 19:20:19'),(1463,'LOAD','LOADER-001','DEMO-1791544819217','2026-10-09 19:20:19','2026-10-09 19:20:19','{\"batchNos\": [\"SP20261003286878\"], \"loadTime\": \"2026-10-09 19:20:10\", \"vehicleNo\": \"京A·12345\", \"driverName\": \"张师傅\"}','LOADER-001',2,'cold_chain_transport',42,NULL,NULL,NULL,NULL,'2026-10-09 19:20:19'),(1464,'LOAD','LOADER-001','DEMO-1791544819427','2026-10-09 19:20:19','2026-10-09 19:20:19','{\"batchNos\": [\"SP-TEST-0001\"], \"loadTime\": \"2026-10-09 19:20:09\", \"vehicleNo\": \"京A·12345\", \"driverName\": \"张师傅\"}','LOADER-001',2,'cold_chain_transport',43,NULL,NULL,NULL,NULL,'2026-10-09 19:20:19');
